191	        notify();
192	    }, 250);
193	    searchInput.addEventListener('input', debouncedSearch);
194	
195	    bar.appendChild(searchInput);
196	
197	    // ---- Repository filter dropdown ----
198	    let repos = [];
199	    try {
200	        repos = await api.repositories.list();
201	    } catch (err) {
202	        showToast(err.message || 'Failed to load repositories for filter.', 'error');
203	    }
204	
205	    if (Array.isArray(repos) && repos.length > 0) {
206	        const repoSelect = document.createElement('select');
207	        repoSelect.className = 'form-select project-filter-repo';
208	        repoSelect.setAttribute('aria-label', 'Filter by repository');
209	
210	        const allOpt = document.createElement('option');
211	        allOpt.value       = '';
212	        allOpt.textContent = 'All repositories';
213	        repoSelect.appendChild(allOpt);
214	
215	        repos.forEach((repo) => {
216	            const opt = document.createElement('option');
217	            opt.value       = repo.id || repo.Id || '';
