219	            if (opt.value === state.repoId) opt.selected = true;
220	            repoSelect.appendChild(opt);
221	        });
222	
223	        repoSelect.addEventListener('change', () => {
224	            state.repoId = repoSelect.value;
225	            notify();
226	        });
227	
228	        bar.appendChild(repoSelect);
229	    }
230	
231	    // ---- Sort selector ----
232	    const sortSelect = document.createElement('select');
233	    sortSelect.className = 'form-select project-filter-sort';
234	    sortSelect.setAttribute('aria-label', 'Sort projects');
235	
236	    const sortOptions = [
